/** Dấu vết mỗi lần claim và phân công có kiểm tra phiên ưu tiên. See docs V2/V3 for operation-level invariants. */
export const dispatchAttempts = pgTable(
  "dispatch_attempts",
  {
    /** Định danh bản ghi */
    id: uuid("id").primaryKey().defaultRandom(),
    /** Tenant sở hữu dữ liệu */
    tenantId: uuid("tenant_id").notNull(),
    /** Tham chiếu dispatch_queue.id */
    queueId: uuid("queue_id").notNull(),
    /** Tham chiếu work_orders.id */
    workOrderId: uuid("work_order_id").notNull(),
    /** Tham chiếu ticket_triage_decisions.id */
    decisionId: uuid("decision_id").notNull(),
    /** Version hàng đợi khi claim */
    queueVersion: bigint("queue_version", { mode: "number" }).notNull(),
    /** Token chống worker hết lease ghi kết quả */
    fencingToken: bigint("fencing_token", { mode: "number" }).notNull(),
    /** Worker đang claim */
    workerId: text("worker_id").notNull(),
    /** 10/20/30/40 chụp tại claim */
    priorityRankSnapshot: integer("priority_rank_snapshot").notNull(),
    /** Lane khẩn tại claim */
    emergencySnapshot: boolean("emergency_snapshot").notNull(),
    /** claimed/offered/no_capacity/stale/expired/failed */
    status: text("status").notNull(),
    /** Thời điểm claim */
    claimedAt: timestamp("claimed_at", { withTimezone: true }).notNull(),
    /** Hết hạn claim */
    leaseUntil: timestamp("lease_until", { withTimezone: true }).notNull(),
    /** Tham chiếu work_assignments.id */
    assignmentId: uuid("assignment_id"),
    /** Kết thúc attempt */
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    /** Lý do không phân công hoặc stale */
    reason: text("reason"),
    /** Khóa chống lặp mỗi queue */
    idempotencyKey: text("idempotency_key").notNull(),
    /** Thời điểm server ghi nhận */
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    /** Thời điểm cập nhật bởi transaction nghiệp vụ */
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t): PgTableExtraConfigValue[] => [
    foreignKey({
      name: "dispatch_attempts_tenant_id_fk",
      columns: [t.tenantId],
      foreignColumns: [tenants.id],
    }).onDelete("restrict"),
    foreignKey({
      name: "dispatch_attempts_queue_id_fk",
      columns: [t.tenantId, t.queueId],
      foreignColumns: [dispatchQueue.tenantId, dispatchQueue.id],
    }).onDelete("restrict"),
    foreignKey({
      name: "dispatch_attempts_work_order_id_fk",
      columns: [t.tenantId, t.workOrderId],
      foreignColumns: [workOrders.tenantId, workOrders.id],
    }).onDelete("restrict"),
    foreignKey({
      name: "dispatch_attempts_decision_id_fk",
      columns: [t.tenantId, t.decisionId],
      foreignColumns: [
        ticketTriageDecisions.tenantId,
        ticketTriageDecisions.id,
      ],
    }).onDelete("restrict"),
    foreignKey({
      name: "dispatch_attempts_assignment_id_fk",
      columns: [t.tenantId, t.assignmentId],
      foreignColumns: [workAssignments.tenantId, workAssignments.id],
    }).onDelete("restrict"),
    unique("dispatch_attempts_tenant_key_uq").on(t.tenantId, t.id),
    pgPolicy("dispatch_attempts_tenant_policy", {
      for: "all",
      using: sql`tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid`,
      withCheck: sql`tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid`,
    }),
    unique("dispatch_attempts_unique_0").on(t.queueId, t.idempotencyKey),
    unique("dispatch_attempts_unique_1").on(t.queueId, t.fencingToken),
    check(
      "dispatch_attempts_check_0",
      sql`priority_rank_snapshot IN (10,20,30,40)`,
    ),
    check(
      "dispatch_attempts_check_1",
      sql`status<>'offered' OR assignment_id IS NOT NULL`,
    ),
    check(
      "dispatch_attempts_check_2",
      sql`status IN ('claimed','offered','no_capacity','stale','expired','failed')`,
    ),
  ],
);

